  )
} else {
  bd <- get("bill_data", envir = .envir_result)
  has_filter <- grepl("filter\\s*\\(", code) && grepl("Adelie", code) && grepl("2007", code)
  has_mutate <- grepl("mutate\\s*\\(", code) && grepl("bill_area", code)
  if (is.data.frame(bd) && nrow(bd) == 50 && "bill_area" %in% names(bd) && has_filter && has_mutate) {
    list(
      correct = TRUE,
      type = "success",
      message = "50 Adelie penguins from 2007 with a `bill_area` column — ready for a one-sample check."
    )
  } else if (!has_filter || !has_mutate) {
    list(
      correct = FALSE,
      type = "info",
      message = "Use `filter(species == \"Adelie\", year == 2007)` and `mutate(bill_area = bill_length_mm * bill_depth_mm)`."
    )
  } else {
    list(
      correct = FALSE,
      type = "info",
